/**
 * Redis Session Manager
 * Handles session persistence, resumption, and timeout management
 */

const redis = require('redis');

require('dotenv').config();

class SessionManager {
  constructor(redisConfig = {}) {
    this.redisConfig = {
      url: process.env.REDIS_URL,
      ...redisConfig
    };

    this.client = null;
    this.initialized = false;
  }

  async initialize() {
    try {
      this.client = redis.createClient(this.redisConfig);

      this.client.on('error', (err) => {
        console.error('[SessionManager] Redis client error', err);
      });

      await this.client.connect();
      console.log('[SessionManager] Redis client connected successfully', JSON.stringify(this.redisConfig));
      this.initialized = true;
      return true;
    } catch (error) {
      console.error('[SessionManager] Failed to initialize Redis', error);
      return false;
    }
  }

  async createSession(sessionId, sessionData, ttl = 3600) {
    try {
      const key = `session:${sessionId}`;
      const data = {
        ...sessionData,
        createdAt: new Date().toISOString(),
        lastUpdated: new Date().toISOString(),
        status: 'active'
      };

      console.log('[SessionManager] createSession', JSON.stringify({ sessionId, key, ttl, data }));
      await this.client.setEx(key, ttl, JSON.stringify(data));
      return { success: true, sessionId };
    } catch (error) {
      console.error('[SessionManager] Error creating session', error);
      return { success: false, error: error.message };
    }
  }

  async getSession(sessionId) {
    try {
      const key = `session:${sessionId}`;
      const data = await this.client.get(key);
      console.log('[SessionManager] getSession', JSON.stringify({ sessionId, key, exists: Boolean(data) }));

      if (!data) {
        return { exists: false, data: null };
      }

      return { exists: true, data: JSON.parse(data) };
    } catch (error) {
      console.error('[SessionManager] Error retrieving session', error);
      return { exists: false, error: error.message };
    }
  }

  async updateSession(sessionId, updates, ttl = null) {
    try {
      const key = `session:${sessionId}`;
      const sessionResult = await this.getSession(sessionId);

      if (!sessionResult.exists) {
        return { success: false, error: 'Session not found' };
      }

      const currentData = sessionResult.data;
      const updatedData = {
        ...currentData,
        ...updates,
        lastUpdated: new Date().toISOString()
      };

      console.log('[SessionManager] updateSession', JSON.stringify({ sessionId, key, updates, updatedData }));

      if (ttl) {
        await this.client.setEx(key, ttl, JSON.stringify(updatedData));
      } else {
        const currentTTL = await this.client.ttl(key);
        if (currentTTL > 0) {
          await this.client.setEx(key, currentTTL, JSON.stringify(updatedData));
        } else {
          await this.client.set(key, JSON.stringify(updatedData));
        }
      }

      return { success: true, data: updatedData };
    } catch (error) {
      console.error('[SessionManager] Error updating session', error);
      return { success: false, error: error.message };
    }
  }

  async setSessionTimeout(sessionId, timeout) {
    try {
      const key = `session:${sessionId}`;
      await this.client.expire(key, timeout);
      console.log('[SessionManager] setSessionTimeout', JSON.stringify({ sessionId, key, timeout }));
      return { success: true };
    } catch (error) {
      console.error('[SessionManager] Error setting timeout', error);
      return { success: false, error: error.message };
    }
  }

  async storeResponse(sessionId, response) {
    try {
      const responseKey = `responses:${sessionId}`;
      const responses = await this.client.get(responseKey);
      const responsesArray = responses ? JSON.parse(responses) : [];

      responsesArray.push({
        ...response,
        timestamp: new Date().toISOString()
      });

      console.log('[SessionManager] storeResponse', JSON.stringify({ sessionId, responseKey, response }));
      await this.client.set(responseKey, JSON.stringify(responsesArray));
      return { success: true };
    } catch (error) {
      console.error('[SessionManager] Error storing response', error);
      return { success: false, error: error.message };
    }
  }

  async getResponses(sessionId) {
    try {
      const responseKey = `responses:${sessionId}`;
      const data = await this.client.get(responseKey);
      const responses = data ? JSON.parse(data) : [];
      console.log('[SessionManager] getResponses', JSON.stringify({ sessionId, responseKey, count: responses.length }));
      return { success: true, responses };
    } catch (error) {
      console.error('[SessionManager] Error retrieving responses', error);
      return { success: false, error: error.message };
    }
  }

  async close() {
    if (this.client) {
      await this.client.quit();
    }
  }

  async linkATSession(internalSessionId, atSessionId, flowId, currentNodeId) {
    return this.updateSession(internalSessionId, {
      atSessionId,
      flowId,
      currentNodeId,
      linkedAt: new Date().toISOString()
    });
  }

  async getSessionByATSession(atSessionId) {
    const key = `atmap:${atSessionId}`;
    const internalId = await this.client.get(key);
    if (!internalId) return { exists: false };

    return this.getSession(internalId);
  }

  async setWaitingNode(sessionId, nodeId, waitConfig = {}) {
    return this.updateSession(sessionId, {
      currentNodeId: nodeId,
      waitingSince: new Date().toISOString(),
      waitConfig
    });
  }

  async deleteSession(sessionKey) {
    try {
      const key = `session:${sessionKey}`;
      await this.client.del(key);
      console.log('[SessionManager] deleteSession', JSON.stringify({ sessionKey, key }));
      return { success: true };
    } catch (error) {
      console.error('[SessionManager] Error deleting session', error);
      return { success: false, error: error.message };
    }
  }

  async getAllSessions(pattern = '*') {
    try {
      const keys = await this.client.keys(`session:${pattern}`);
      const sessions = [];
      for (const key of keys) {
        const data = await this.client.get(key);
        sessions.push(JSON.parse(data));
      }
      console.log('[SessionManager] getAllSessions', JSON.stringify({ pattern, count: sessions.length }));
      return { success: true, sessions };
    } catch (error) {
      console.error('[SessionManager] Error listing sessions', error);
      return { success: false, error: error.message };
    }
  }
}

module.exports = SessionManager;